        check("compute(ADD, 2, 3)", 5, Calc.compute(Calc.Op.ADD, 2, 3));
        check("compute(SUB, 10, 4)", 6, Calc.compute(Calc.Op.SUB, 10, 4));
        check("compute(MUL, 3, 4)", 12, Calc.compute(Calc.Op.MUL, 3, 4));
        check("Op.ADD.apply(7, 8)", 15, Calc.Op.ADD.apply(7, 8));
