public class Calc {

    public enum Op {
        ADD {
            public int apply(int a, int b) {
                return a + b;
            }
        },
        SUB {
            public int apply(int a, int b) {
                return a - b;
            }
        },
        MUL {
            public int apply(int a, int b) {
                return a * b;
            }
        };

        public abstract int apply(int a, int b);
    }

    public static int compute(Op op, int a, int b) {
        return op.apply(a, b);
    }
}
